/**
 * @param {string} cdok - cdok number
 * @param {string} lang - language
 * @param {string} jv - j version
 * @param {string} ela - ela version
 * @param {date} d - date object
 * @param {number} cp - current page
 * @param {number} tp - total pages
 */
function getBarcode(cdok, lang, jv, ela, d, cp, tp)
{
	var appBarcode = Footer_Line_APPCode.value;
	var bc;

	if(!appBarcode || appBarcode == "99"){
		bc = createBarcode(cdok, lang, jv, ela, d, cp, tp);
	}
	else{
		var code = appBarcode.substring(0, appBarcode.length - 4);
		bc = createAppBarcode(code, cp, tp);
	}

	if(bc){
		return bc;
	}
	return null;
}

/**
 * barcode builder
 * @param {string} cdok CDOK Number
 * @param {string} jv
 * @param {string} ela ELA Version
 * @param {date} d current date
 * @param {number} cp current page
 * @param {number} tp total pages
 * @param {number} n predefined number
 * @returns string for barcode
 */
function createBarcode(cdok, lang, jv, ela, d, cp, tp)
{
	var code= "0101" + 
			  trim(cdok) + 
			  getLanguageCode(trim(lang)) + 
			  getVersion(trim(jv)) +
			  getVersion(trim(ela)) +
			  soGlobal.formatDate("ddmmyyyy",d) +
			  formatPageNr(cp) +          
			  formatPageNr(tp);

	return code + calculateChecksum(code);
}

/**
 * @param {string} appCode
 * @param {number} cp current page
 * @param {number} tp total pages
 * @returns string for barcode
 */
function createAppBarcode(appCode, cp, tp) 
{
	var code = appCode + formatPageNr(cp) + formatPageNr(tp);
	return code + calculateChecksum(code);
}

/**
 * @param {string} lang - language represented by one letter
 * @returns language code
 */
function getLanguageCode(lang)
{
	lang = lang.toUpperCase();

	switch(lang) {
		case "DE": return "01";
		case "FR": return "02";
		case "IT": return "03";
		case "EN": return "04";
		case "SP": return "05";
		case "PT": return "06";
		case "NE": return "07";  //Netherlands
		case "QQ": return "20";
		case "TT": return "21";
		case "XX": return "99";

