}

/**
 * @param {number} page page number
 * @return formatted page string
 */
function formatPageNr(page)
{
	if(page > 99){
		app.alert("Pagenumber to big, no more pages then 99 is suported number given is (" + newNumber +") length=" + newNumber.length);
		return newNumber % 100;
	}
	else{
		if(page < 10) return "0" + page;
		return page.toString();
	}
}

/**
 * @param {string} v version string
 * @return formatted version string
 */
function getVersion(v)
{
	var a = v.match(/\d+/);
	if(a && a[0]){
		var n = parseInt(a[0]);
		if(typeof n == "number"){
			if(n > 99) app.alert("Version string " + n + " to big");	
			if(n < 10) return "0" + n;
			return n.toString();
		}
	}
}

function calculateChecksum(code)
{
	var even = 0;
	var odd = 0;

	for(var i=code.length - 1; i>=0; i--){
		if(i % 2 == 0){
			odd += parseInt(code[i]);
		}
		else{
			even += parseInt(code[i]);
		}
	}

	var finalVal = (3 * odd) + even;	
	var strRem = finalVal % 10; 
	if(strRem == 0){
		return 0;
	}
	else{
		return  10 - (finalVal % 10);
	}
}

function trim(str, chars)
{
	return ltrim(rtrim(str, chars), chars);
}

function ltrim(str, chars)
{
    chars = chars || "\\s";
    return str.replace(new RegExp("^[" + chars + "]+"), "");
}

function rtrim(str, chars)
{
    chars = chars || "\\s";
    return str.replace(new RegExp("[" + chars + "]+$"), "");
}

/**
 * @param {object} first - reference instance
 * @param {object} second - additional instance to be added
 */
var insertAndSynchronize = function(first, second)
{
	if(first.instanceManager.count == second.instanceManager.count){
		if(first.instanceManager.max == -1 || first.instanceManager.count < first.instanceManager.max){
			insertNode(first,second);
		}
	}
}

/**
 * @param {object} first - reference instance
 * @param {object} second - instance to be removed
 */
function removeAndSynchronize(first, second)
{
	if(first.instanceManager.count == second.instanceManager.count){
		removeNode(second,first.instanceIndex);
		removeNode(first);
	}
}

/**
 * @param {object} first - node you want to be added
 * @param {object} [second] - additional node to be added. this is optional
 */
function insertNode(first, second)
{
	var doInsert = true;

	if(first.instanceManager.max > 0){
		if(first.instanceManager.count == first.instanceManager.max){
			doInsert = false;
		}
	}

	if(doInsert){
		first.instanceManager.insertInstance(first.instanceIndex + 1);
		if(second){
			second.instanceManager.insertInstance(first.instanceIndex + 1);
		}
	}
}

/*
 * @param {object} node - node you want to be removed
 * @param {number} [indexFirst] - instanceIndex of first, used only when synchronizing
 */
function removeNode(node, indexFirst)
{
	if(node.instanceManager.count > 1){
		node.instanceManager.removeInstance(indexFirst || node.instanceIndex);
		return true;
	}
	else{
		return false;
	}
}

/*
 * @param {object} node - first node you want to be added
 * @param {array} nodes - array of nodes to be also added alongside "first"
 */
function insertNodes(node, nodes)
{
	var doInsert = true;

	if(first.instanceManager.max > 0){
		if(first.instanceManager.count == first.instanceManager.max){
			doInsert = false;
		}
	}

	if(doInsert){
		first.instanceManager.insertInstance(first.instanceIndex + 1);
		if(nodes && nodes.length > 0){
			for(var i=0,l=nodes.length; i<l; i++){
				nodes[i].instanceManager.insertInstance(first.instanceIndex + 1);
			}
		}
	}
}

/*
 * @param {object} node - node you want to be removed
 * @param {array} nodes - array of nodes to be also removed alongside "node"
 * returns true if successful, false if failed
 */
function removeNodes(node, nodes)
{
	var indexFirst = node.instanceIndex;

	if(node.instanceManager.count > 1){
		node.instanceManager.removeInstance(indexFirst);
		if(nodes && nodes.length > 0){
			for(var i=0,l=nodes.length; i<l; i++){
				nodes[i].instanceManager.removeInstance(indexFirst);
			}
		}	
		return true;
	}
	return false;
}

/**
 * @param {number} total - total of instances
 * @param {number} current - current instance index
 */
function getPosition(total, current)
{
	if(total > 1){
		return current + 1;
	}
	else{
		return null;
	}
}

